// Real Chrome DOM regression for desktop screenshot settings and case input audit.
const assert=require('node:assert/strict'),http=require('node:http'),fs=require('node:fs/promises'),os=require('node:os'),path=require('node:path');
const {spawn}=require('node:child_process'),{once}=require('node:events'),{setTimeout:delay}=require('node:timers/promises');
async function until(fn){for(let i=0;i<150;i++){const v=await fn();if(v)return v;await delay(100);}throw Error('Timed out');}
(async()=>{
 const staticRoot=path.resolve(__dirname,'../static'),shellFile=path.resolve(__dirname,'../../desktop/shell.html'),profile=await fs.mkdtemp(path.join(os.tmpdir(),'streamanalyzer-model-images-ui-'));
 let settings={provider:'openai-compatible',base_url:'https://model.example.test/v1',model:'vision-test',has_api_key:true,image_input:'text'},testFailure=false;const posts=[];
 const server=http.createServer(async(req,res)=>{try{
  if(req.url.startsWith('/model-settings')){assert.equal(req.headers['x-streamanalyzer-settings'],'fixture-token');res.setHeader('Content-Type','application/json');if(req.method==='POST'){let body='';for await(const c of req)body+=c;const draft=JSON.parse(body);posts.push({path:req.url,draft});if(req.url.endsWith('/test')){if(testFailure){res.writeHead(502);res.end(JSON.stringify({error:'HTTP 401：API Key 无效'}));}else res.end(JSON.stringify({elapsed_ms:12}));return;}settings={...settings,...draft,has_api_key:true};delete settings.api_key;}res.end(JSON.stringify(settings));return;}
  if(req.url==='/api/diagnostics/config'){res.setHeader('Content-Type','application/json');res.end(JSON.stringify({model_configured:true,model_provider:settings.provider,model_name:settings.model,model_image_input:settings.image_input}));return;}
  if(req.url.startsWith('/api/')){res.setHeader('Content-Type','application/json');res.end('[]');return;}
  if(req.url==='/shell'){const body=(await fs.readFile(shellFile,'utf8')).replace('{{.SettingsToken}}','fixture-token').replace('{{.WorkbenchURL}}','/diagnostics');res.setHeader('Content-Type','text/html');res.end(body);return;}
  const name=req.url==='/diagnostics'?'diagnostics.html':req.url.replace(/^\/static\//,'');const body=await fs.readFile(path.join(staticRoot,name));res.setHeader('Content-Type',name.endsWith('.js')?'text/javascript':name.endsWith('.css')?'text/css':'text/html');res.end(body);
 }catch(error){res.writeHead(500);res.end(error.message);}});server.listen(0,'127.0.0.1');await once(server,'listening');
 const chrome=spawn(process.env.CHROME_BIN||'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',['--headless=new','--no-first-run',`--user-data-dir=${profile}`,'--remote-debugging-port=0','about:blank'],{stdio:'ignore'});let ws;
 try{
  const debug=await until(()=>fs.readFile(path.join(profile,'DevToolsActivePort'),'utf8').catch(()=>'')),tabs=await(await fetch(`http://127.0.0.1:${debug.split('\n')[0]}/json/list`)).json();ws=new WebSocket(tabs.find(v=>v.type==='page').webSocketDebuggerUrl);await once(ws,'open');let sequence=0;const pending=new Map(),errors=[];
  ws.addEventListener('message',({data})=>{const m=JSON.parse(data);if(m.id){const p=pending.get(m.id);pending.delete(m.id);m.error?p.reject(m.error):p.resolve(m.result);}else if(m.method==='Runtime.exceptionThrown')errors.push(m.params);});
  const cdp=(method,params={})=>new Promise((resolve,reject)=>{pending.set(++sequence,{resolve,reject});ws.send(JSON.stringify({id:sequence,method,params}));});const evaluate=async expression=>{const r=await cdp('Runtime.evaluate',{expression,returnByValue:true,awaitPromise:true,replMode:true});if(r.exceptionDetails)throw Error(JSON.stringify(r.exceptionDetails));return r.result.value;};
  const frameEval=code=>evaluate(`document.getElementById('workbench').contentWindow.eval(${JSON.stringify(code)})`);
  await cdp('Runtime.enable');await cdp('Page.navigate',{url:`http://127.0.0.1:${server.address().port}/shell`});await until(()=>frameEval(`!document.getElementById('model-settings').hidden`).catch(()=>false));
  await frameEval(`document.getElementById('model-settings').click()`);await until(()=>evaluate(`document.getElementById('settings-dialog').open&&!document.getElementById('settings-fields').disabled`));
  assert.equal(await evaluate(`document.getElementById('settings-image-input').value`),'text');assert.match(await evaluate(`document.getElementById('image-input-hint').textContent`),/图片能力在实际补查时确认/);
  await evaluate(`document.getElementById('settings-image-input').value='auto';document.getElementById('settings-image-input').dispatchEvent(new Event('change',{bubbles:true}));document.getElementById('test-settings').click()`);await until(()=>evaluate(`document.getElementById('settings-status').textContent.includes('文本连接成功')`));assert.equal(posts.at(-1).draft.image_input,'auto');assert.equal(settings.image_input,'text','connection test unexpectedly saved draft');
  await evaluate(`document.getElementById('settings-image-input').value='text';document.getElementById('settings-image-input').dispatchEvent(new Event('change',{bubbles:true}))`);assert.equal(await evaluate(`document.getElementById('settings-status').textContent`),'');
  await evaluate(`document.getElementById('settings-image-input').value='auto';document.getElementById('settings-image-input').dispatchEvent(new Event('change',{bubbles:true}));document.getElementById('settings-form').requestSubmit()`);await until(()=>frameEval(`currentModel?.image_input==='auto'`));assert.equal(settings.image_input,'auto');
  await frameEval(`document.getElementById('model-settings').click()`);await until(()=>evaluate(`!document.getElementById('settings-fields').disabled`));assert.equal(await evaluate(`document.getElementById('settings-image-input').value`),'auto');
  await evaluate(`document.getElementById('settings-image-input').value='text';document.getElementById('settings-provider').value='deepseek';document.getElementById('settings-provider').dispatchEvent(new Event('change'));document.getElementById('settings-model').value='text-fixture';document.getElementById('settings-key').value='draft-key'`);assert.equal(await evaluate(`document.getElementById('settings-image-input').value`),'text','provider switch discarded deliberate text policy');testFailure=true;await evaluate(`document.getElementById('test-settings').click()`);await until(()=>evaluate(`document.getElementById('settings-status').textContent.includes('HTTP 401')`));await evaluate(`document.getElementById('close-settings').click()`);assert.equal(settings.image_input,'auto');
  const assets=['before.jpg','during.jpg','after.jpg'].map(name=>({name:'stalls/S001/'+name,kind:'screenshot',bytes:128,sha256:'a'.repeat(64),media_time_ms:0}));const refs=assets.map((v,i)=>({...v,id:'S001-I00'+(i+1),case_id:'S001'}));
  const item={id:'S001',stall_index:1,player_revision:2,status:'complete',stall:{start_ms:6000,end_ms:7500,duration_ms:1500},correlation:{source:'same_capture',window_start_ms:3000,window_end_ms:10500,findings:[]},media:{status:'ready',assets},model_state:'complete',explanation:{provider:'openai-compatible',model:'fixture',summary:'核对截图与时序',hypotheses:[{claim:'源流画面需要结合时序验证',evidence_ids:['S001-I001'],next_check:'核对源端'}],input_evidence:{version:1,case_id:'S001',player_revision:2,requested_mode:'auto',mode:'vision',images:refs}}};
  await frameEval(`window.inputFixture=${JSON.stringify(item)};currentID='model-input';currentReport={manifest:{protocol:'rtsp'}};document.getElementById('report').hidden=false;document.getElementById('stall-investigations').hidden=false;document.getElementById('stall-investigation-results').replaceChildren(renderInvestigation(inputFixture));document.querySelector('.stall-investigation').open=true;`);
  let text=await frameEval(`document.querySelector('.model-input-evidence').textContent`);assert.ok(text.includes('本次为图文解读 · 3 张截图')&&!text.includes('未发送截图像素'));assert.ok(text.includes('媒体时间 0 ms'));assert.equal(await frameEval(`document.querySelectorAll('#case-S001-I001').length`),1);assert.equal(await frameEval(`document.querySelector('a[href="#case-S001-I001"]').getAttribute('href')`),'#case-S001-I001');
  for(const width of [1440,375]){await cdp('Emulation.setDeviceMetricsOverride',{width,height:1000,deviceScaleFactor:1,mobile:false});assert.equal(await frameEval(`document.documentElement.scrollWidth>innerWidth`),false,'case audit overflow at '+width);}
  await frameEval(`inputFixture.explanation.input_evidence={...inputFixture.explanation.input_evidence,mode:'text',fallback_code:'images_unsupported',images:[],attempted_images:inputFixture.explanation.input_evidence.images};inputFixture.explanation.hypotheses=[];document.getElementById('stall-investigation-results').replaceChildren(renderInvestigation(inputFixture));document.querySelector('.stall-investigation').open=true;`);
  text=await frameEval(`document.querySelector('.model-input-evidence').textContent`);assert.ok(text.includes('已尝试发送 3 张截图')&&!text.includes('未发送截图像素'));assert.equal(await frameEval(`document.querySelectorAll('#case-S001-I001').length`),0);
  await frameEval(`inputFixture.explanation.input_evidence={...inputFixture.explanation.input_evidence,requested_mode:'text',fallback_code:'disabled',attempted_images:[]};document.getElementById('stall-investigation-results').replaceChildren(renderInvestigation(inputFixture));`);assert.match(await frameEval(`document.querySelector('.model-input-evidence').textContent`),/本次仅发送时序文本，未发送截图像素/);
  await frameEval(`delete inputFixture.explanation.input_evidence;document.getElementById('stall-investigation-results').replaceChildren(renderInvestigation(inputFixture));`);assert.match(await frameEval(`document.querySelector('.model-input-evidence').textContent`),/该历史结果未记录截图输入方式/);
  assert.equal(await frameEval(`new Set(Array.from(document.querySelectorAll('[id]')).map(v=>v.id)).size===document.querySelectorAll('[id]').length`),true);assert.equal(errors.length,0,JSON.stringify(errors));console.log(JSON.stringify({result:'PASS',cases:['desktop image policy draft/test/save/hot reload','connection test accurately text only','provider switch preserves deliberate text','exact test failure and cancel no-save','vision IDs and file links','attempted versus final evidence','zero media time and legacy unknown','375/1440 layout and unique IDs']}));
 }finally{ws?.close();chrome.kill('SIGTERM');await once(chrome,'exit').catch(()=>{});await new Promise(r=>server.close(r));await fs.rm(profile,{recursive:true,force:true,maxRetries:5,retryDelay:100});}
})().catch(error=>{console.error(error);process.exitCode=1;});
